pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivateBank} from "../src/PrivateBank.sol";

contract InvMutTest is Test {
    PrivateBank c;
    function setUp() public { c = new PrivateBank(address(this)); }
    function testFuzz_property(uint128 am, address actor) public {
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        vm.assume(am > 0 && am < 1 ether);
        vm.deal(actor, am * 2);
        vm.prank(actor);
        c.Deposit{value: am}();
        uint balAfterDeposit = c.balances(actor);
        vm.prank(actor);
        bool ok = true;
        try c.CashOut(balAfterDeposit) { } catch { ok = false; }
        assertTrue(ok == false);
    }
}
